import { FIELD_SEP, MAX_BODY_CHARS, RECORD_SEP } from "./changelogLimits.js";

/***
 * MARK: parseGitLog
 * @description Parses NUL/RS-delimited `git log` output into changelog
 *   entries, newest-first as emitted. Bodies are capped at MAX_BODY_CHARS
 *   with a `bodyTruncated` flag; malformed records (too few fields, blank
 *   SHA) are skipped rather than failing the whole bake, so one odd commit
 *   can never empty the dialog.
 * @example parseGitLog(raw) => [{ sha, shortSha, subject, body, bodyTruncated, author, authorEmail, date }]
 * @param {string} raw - Raw stdout from the git log invocation.
 * @returns {Array<Object>} Parsed entries, newest first.
 ***/
export function parseGitLog(raw) {
	if (typeof raw !== "string" || raw.length === 0) return [];
	const entries = [];
	for (const record of raw.split(RECORD_SEP)) {
		if (!record.trim()) continue;
		const fields = record.split(FIELD_SEP);
		if (fields.length < 7) continue;
		const [sha, shortSha, author, authorEmail, date, subject, ...bodyParts] = fields;
		if (!sha || !sha.trim()) continue;
		// A body holding a literal NUL is near-impossible (git truncates
		// messages at NUL), but rejoin defensively so extra separators never
		// drop body text.
		const body = bodyParts.join(FIELD_SEP).replace(/^\n/, "").replace(/\s+$/, "");
		const bodyTruncated = body.length > MAX_BODY_CHARS;
		entries.push({
			sha: sha.trim(),
			shortSha: (shortSha || "").trim(),
			subject: (subject || "").trim(),
			body: bodyTruncated ? body.slice(0, MAX_BODY_CHARS) : body,
			bodyTruncated,
			author: (author || "").trim(),
			authorEmail: (authorEmail || "").trim(),
			date: (date || "").trim(),
		});
	}
	return entries;
}

/***
 * MARK: admin commit patterns
 * @description Why each pattern is automation noise rather than shipped work:
 *   `KainBain:` subjects are engine auto-commits (pending-work snapshots,
 *   converge/merge-latest syncs); `kb/<uuid>` subjects are per-stage runner
 *   output commits; every listed merge shape only syncs branches (task work
 *   lands on the default branch as squash commits with their own subjects,
 *   so dropping the sync merge never hides the work itself). A merge that
 *   carries real review wording (for example `Merge main: keep the
 *   model-reporting fix`) matches none of these and is kept.
 ***/
const KAINBAIN_PREFIX = "KainBain:";
const RUNNER_OUTPUT_SUBJECT = /^kb\/[0-9a-f-]{8,}/i;
const REMOTE_TRACKING_MERGE = /^merge remote-tracking branch\b/i;
const LOCAL_BRANCH_MERGE = /^merge\s+branch\b.*\binto\s+kb\/[0-9a-f-]{8,}/i;
const ORIGIN_MERGE = /^merge\s+origin\//i;
const MERGE_INTO_TASK_BRANCH = /\binto\s+kb\/[0-9a-f-]{8,}/i;

/***
 * MARK: isAdminCommitSubject
 * @description Decides whether a commit subject is automation noise that the
 *   changelog should hide: engine auto-commits, runner stage-output commits,
 *   and branch-sync merges. Anything else — human task work, squash-merge
 *   subjects, real merges with review wording — is kept. Unknown shapes
 *   (non-strings, blank lines) count as noise so a malformed subject can
 *   never slip an unreadable row into the dialog.
 * @example isAdminCommitSubject('KainBain: auto-commit pending work') => true
 * @example isAdminCommitSubject("Merge branch 'main' into kb/2b990c4f-2026") => true
 * @example isAdminCommitSubject('Merge origin/main into kb/2b990c4f-2026') => true
 * @example isAdminCommitSubject("Merge remote-tracking branch 'origin/main' into kb/aa-2026") => true
 * @example isAdminCommitSubject('Merge main: keep the model-reporting fix') => false
 * @example isAdminCommitSubject('Harden runner log transport') => false
 * @param {string} subject - The commit subject line.
 * @returns {boolean} True when the commit is automation noise to hide.
 ***/
export function isAdminCommitSubject(subject) {
	if (typeof subject !== "string") return true;
	const line = subject.trim();
	if (line.length === 0) return true;
	if (line.startsWith(KAINBAIN_PREFIX)) return true;
	if (RUNNER_OUTPUT_SUBJECT.test(line)) return true;
	if (REMOTE_TRACKING_MERGE.test(line)) return true;
	if (LOCAL_BRANCH_MERGE.test(line)) return true;
	if (ORIGIN_MERGE.test(line)) return true;
	if (MERGE_INTO_TASK_BRANCH.test(line)) return true;
	return false;
}

import { isAdminCommitSubject } from "./isAdminCommitSubject.js";

/***
 * MARK: filterChangelogEntries
 * @description Drops automation-noise entries (see `isAdminCommitSubject`)
 *   from an already-parsed entry list, keeping newest-first order. Never
 *   throws: a non-list reads as an empty changelog so one malformed source
 *   cannot break the dialog.
 * @example filterChangelogEntries([{ subject: 'KainBain: sync' }]) => []
 * @example filterChangelogEntries([{ subject: 'Fix the queue chip' }]) => [{ subject: 'Fix the queue chip' }]
 * @param {Array<Object>} entries - Parsed changelog entries, newest first.
 * @returns {Array<Object>} The kept entries, newest first.
 ***/
export function filterChangelogEntries(entries) {
	if (!Array.isArray(entries)) return [];
	return entries.filter((entry) => !isAdminCommitSubject(entry?.subject));
}

import React from 'react';
import { useLiveBuild } from './useLiveBuild';
import { InfoTooltip } from '../common/InfoTooltip';
import { ChangelogModal } from './ChangelogModal';

/***
 * MARK: BuildHashTrigger
 * @description Slightly greyed-out monospace `#B<build><·short SHA>` trigger
 *   living in the Now Playing bar's right rail, left of the queue-depth chip.
 *   Clicking (or keyboard-activating) it opens the Kainbain changelog baked
 *   into the live build. Hidden when no build identity is baked (dev and
 *   pre-deploy builds), so it never shows a fabricated hash.
 * @example <BuildHashTrigger />
 ***/
export function BuildHashTrigger() {
  const { buildNumber, commitSha, changelogOpen, setChangelogOpen } = useLiveBuild();

  if (buildNumber == null) return null;

  // The stamped `commit` is sometimes a full 40-char SHA (older bakes) or a
  // version-prefixed tag (`1.0.0-<sha>`): display at most the short 7-char
  // form so a long hash can never crowd the 72px bar at narrow widths. The
  // full value is never needed in the DOM — identity is build number + short.
  // `unknown` / blank stamps (a deploy that could not resolve HEAD) are
  // treated as "no hash" so we never fabricate an identity from garbage.
  const rawSha = typeof commitSha === 'string' && commitSha.trim() !== '' ? commitSha.trim() : null;
  const strippedSha = rawSha
    ? rawSha.includes('-')
      ? rawSha.slice(rawSha.lastIndexOf('-') + 1)
      : rawSha
    : null;
  const sha =
    strippedSha != null && strippedSha !== '' && strippedSha.toLowerCase() !== 'unknown'
      ? strippedSha.slice(0, 7)
      : null;
  const label = sha ? `#B${buildNumber}·${sha}` : `#B${buildNumber}`;
  const accessibleName =
    sha != null
      ? `Build ${buildNumber} (${sha}) of the live deployment — show Kainbain changelog`
      : `Build ${buildNumber} of the live deployment — show Kainbain changelog`;

  return (
    <>
      <InfoTooltip
        title={`Live Production Build #B${buildNumber}`}
        description="Self-deploying production build identifier stamped from atomic counter. Click to view the Kainbain changelog baked into this build."
        behindTheScenes="Reads /status which checks ~/apps/kainbain/build.json; the changelog comes from /deploy/changelog (baked at deploy time)."
        position="top-left"
        className="min-w-0"
      >
        <button
          type="button"
          onClick={() => setChangelogOpen(true)}
          className="px-2 py-1 min-h-[44px] min-w-0 max-w-[36vw] sm:max-w-none rounded-sm text-text-muted hover:text-primary text-xs font-mono select-none border border-transparent hover:border-border-standard flex items-center justify-center cursor-pointer transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-primary"
          aria-label={accessibleName}
          data-testid="build-badge"
        >
          {/* Capped width with ellipsis on phones so a long build number can
              never crowd the idle hint / runner boxes out of the 72px bar;
              the untruncated label stays in the accessible name. */}
          <span className="truncate min-w-0">{label}</span>
        </button>
      </InfoTooltip>
      {changelogOpen && (
        <ChangelogModal buildNumber={buildNumber} onClose={() => setChangelogOpen(false)} />
      )}
    </>
  );
}

